package com.rpb.reservation.workforce.payroll.governance;

import static com.rpb.reservation.workforce.payroll.governance.TemplatePublicationDtos.*;
import com.rpb.reservation.workforce.application.WorkforceJson;
import com.rpb.reservation.workforce.domain.WorkforceException;
import java.time.*;
import java.util.*;
import org.springframework.jdbc.core.JdbcTemplate;
import org.springframework.stereotype.Repository;

@Repository
public class TemplatePublicationRepository {
 private final JdbcTemplate jdbc;private final WorkforceJson json;private final Clock clock;
 public TemplatePublicationRepository(JdbcTemplate jdbc,WorkforceJson json){this(jdbc,json,Clock.systemUTC());}
 @org.springframework.beans.factory.annotation.Autowired public TemplatePublicationRepository(JdbcTemplate jdbc,WorkforceJson json,Clock clock){this.jdbc=jdbc;this.json=json;this.clock=clock;}
 public LocalDate today(){return LocalDate.now(clock.withZone(ZoneId.of("Asia/Singapore")));}
 public record Store(UUID id,UUID companyId,Instant createdAt,boolean active,String name){}
 public record Command(UUID tenantId,UUID actorId,UUID storeId,String action,String payload,String response){}
 public void lock(String key){jdbc.queryForObject("select pg_advisory_xact_lock(hashtextextended(?,0))",Object.class,"workforce.pay.governance:"+key);}
 public Instant now(){return jdbc.queryForObject("select clock_timestamp()",java.sql.Timestamp.class).toInstant();}
 public List<Store> stores(UUID tenant){return jdbc.query("select id,operating_entity_id,created_at,(status='active' and deleted_at is null),display_name from stores where tenant_id=?",(r,n)->new Store(r.getObject(1,UUID.class),r.getObject(2,UUID.class),r.getTimestamp(3).toInstant(),r.getBoolean(4),r.getString(5)),tenant);}
 public boolean inactiveStoreAssigned(UUID tenant,UUID actor,UUID store){return Boolean.TRUE.equals(jdbc.queryForObject("select exists(select 1 from auth_account_store_access where tenant_id=? and account_id=? and store_id=? and deleted_at is null)",Boolean.class,tenant,actor,store));}
 public List<com.rpb.reservation.workforce.application.WorkforceDtos.Option> companyOptions(UUID tenant){return jdbc.query("select c.id,c.display_name from operating_entities c where c.tenant_id=? and c.status='active' and c.deleted_at is null and not exists(select 1 from workforce_company_settings cs where cs.tenant_id=c.tenant_id and cs.company_id=c.id and cs.enabled=false) order by c.display_name,c.id",(r,n)->new com.rpb.reservation.workforce.application.WorkforceDtos.Option(r.getObject(1,UUID.class),r.getString(2)),tenant);}
 public Store store(UUID tenant,UUID id){return stores(tenant).stream().filter(s->s.id().equals(id)).findFirst().orElseThrow(WorkforceException::missing);}
 public boolean companyActive(UUID tenant,UUID id){return Boolean.TRUE.equals(jdbc.queryForObject("select exists(select 1 from operating_entities where tenant_id=? and id=? and status='active' and deleted_at is null) and not exists(select 1 from workforce_company_settings where tenant_id=? and company_id=? and enabled=false)",Boolean.class,tenant,id,tenant,id));}
 public List<Draft> drafts(UUID tenant){return jdbc.query("select snapshot from workforce_pay_template_masters where tenant_id=? order by created_at,id",(r,n)->json.read(r.getString(1),Draft.class),tenant);}
 public Optional<Draft> draft(UUID tenant,UUID id){return jdbc.query("select snapshot from workforce_pay_template_masters where tenant_id=? and id=?",(r,n)->json.read(r.getString(1),Draft.class),tenant,id).stream().findFirst();}
 public void save(UUID tenant,Draft d){int changed=jdbc.update("insert into workforce_pay_template_masters(id,tenant_id,version,snapshot) values(?,?,?,?::jsonb) on conflict(id) do update set version=excluded.version,snapshot=excluded.snapshot,updated_at=now() where workforce_pay_template_masters.tenant_id=excluded.tenant_id",d.id(),tenant,d.version(),json.write(d));if(changed!=1)throw WorkforceException.conflict();}
 public List<Release> releases(UUID tenant){return jdbc.query("select snapshot from workforce_pay_template_releases where tenant_id=? order by master_id,version",(r,n)->json.read(r.getString(1),Release.class),tenant);}
 public Optional<Release> release(UUID tenant,UUID id,long version){return jdbc.query("select snapshot from workforce_pay_template_releases where tenant_id=? and master_id=? and version=?",(r,n)->json.read(r.getString(1),Release.class),tenant,id,version).stream().findFirst();}
 public long latestVersion(UUID tenant,UUID id){return jdbc.queryForObject("select coalesce(max(version),0) from workforce_pay_template_releases where tenant_id=? and master_id=?",Long.class,tenant,id);}
 public Optional<Release> publishedDraft(UUID tenant,UUID id,long version){return jdbc.query("select snapshot from workforce_pay_template_releases where tenant_id=? and master_id=? and draft_version=?",(r,n)->json.read(r.getString(1),Release.class),tenant,id,version).stream().findFirst();}
 public void publish(UUID tenant,Release r){jdbc.update("insert into workforce_pay_template_releases(master_id,tenant_id,version,draft_version,snapshot,published_at,published_by) values(?,?,?,?,?::jsonb,?,?)",r.masterId(),tenant,r.version(),r.draftVersion(),json.write(r),java.sql.Timestamp.from(r.publishedAt()),r.publishedBy());for(var company:r.companyIds())jdbc.update("insert into workforce_pay_template_release_companies(master_id,release_version,tenant_id,company_id) values(?,?,?,?)",r.masterId(),r.version(),tenant,company);for(var shop:r.storeIds())jdbc.update("insert into workforce_pay_template_release_stores(master_id,release_version,tenant_id,company_id,store_id) values(?,?,?,?,?)",r.masterId(),r.version(),tenant,store(tenant,shop).companyId(),shop);}
 public Optional<Adoption> latest(UUID tenant,UUID store,UUID master){return jdbc.query("select snapshot from workforce_pay_template_adoptions where tenant_id=? and store_id=? and master_id=? order by store_version desc limit 1",(r,n)->json.read(r.getString(1),Adoption.class),tenant,store,master).stream().findFirst();}
 public Optional<Adoption> current(UUID tenant,UUID store,UUID master){return currentAt(tenant,store,master,today());}
 public Optional<Adoption> currentAt(UUID tenant,UUID store,UUID master,LocalDate date){return jdbc.query("select a.snapshot from workforce_pay_template_adoptions a join stores s on s.tenant_id=a.tenant_id and s.id=a.store_id and s.operating_entity_id=a.company_id where a.tenant_id=? and a.store_id=? and a.master_id=? and a.effective_from<=? order by a.effective_from desc,a.store_version desc limit 1",(r,n)->json.read(r.getString(1),Adoption.class),tenant,store,master,date).stream().findFirst();}
 public List<ScheduledAdoption> scheduled(UUID tenant,UUID store,UUID master){return jdbc.query("select a.snapshot,a.effective_from from workforce_pay_template_adoptions a join stores s on s.tenant_id=a.tenant_id and s.id=a.store_id and s.operating_entity_id=a.company_id where a.tenant_id=? and a.store_id=? and a.master_id=? and a.effective_from>? order by a.effective_from,a.store_version",(r,n)->new ScheduledAdoption(json.read(r.getString(1),Adoption.class),r.getObject(2,LocalDate.class)),tenant,store,master,today());}
 public LocalDate effectiveDate(UUID tenant,UUID adoption){return jdbc.queryForObject("select effective_from from workforce_pay_template_adoptions where tenant_id=? and id=?",LocalDate.class,tenant,adoption);}
 /** Stable ownership resolution for later request/evidence services; never inferred from shared mapping. */
 public Adoption adoption(UUID tenant,UUID store,UUID company,UUID id){return jdbc.query("select snapshot from workforce_pay_template_adoptions where tenant_id=? and store_id=? and company_id=? and id=?",(r,n)->json.read(r.getString(1),Adoption.class),tenant,store,company,id).stream().findFirst().orElseThrow(WorkforceException::missing);}
 public void adopt(UUID tenant,Adoption a){adoptEffective(tenant,a,today());}
 public void adoptEffective(UUID tenant,Adoption a,LocalDate effectiveDate){jdbc.update("insert into workforce_pay_template_adoptions(id,tenant_id,master_id,release_version,company_id,store_id,store_version,materialized_template_id,snapshot,enabled_by,effective_from) values(?,?,?,?,?,?,?,?,?::jsonb,?,?)",a.id(),tenant,a.masterId(),a.releaseVersion(),a.companyId(),a.storeId(),a.storeVersion(),a.materializedTemplateId(),json.write(a),a.enabledBy(),effectiveDate);}
 public <T>Optional<T> replay(UUID tenant,UUID actor,UUID store,UUID command,String action,Object payload,Class<T> type){var found=jdbc.query("select tenant_id,actor_id,store_id,action,payload,response from workforce_pay_template_commands where id=?",(r,n)->new Command(r.getObject(1,UUID.class),r.getObject(2,UUID.class),r.getObject(3,UUID.class),r.getString(4),r.getString(5),r.getString(6)),command).stream().findFirst();if(found.isEmpty())return Optional.empty();var c=found.get();if(!c.tenantId().equals(tenant)||!c.actorId().equals(actor)||!c.storeId().equals(store)||!c.action().equals(action)||!sameJson(c.payload(),json.write(payload)))throw WorkforceException.conflict();return Optional.of(json.read(c.response(),type));}
 public void command(UUID tenant,UUID actor,UUID store,UUID command,String action,Object payload,Object response){jdbc.update("insert into workforce_pay_template_commands(id,tenant_id,actor_id,store_id,action,payload,response) values(?,?,?,?,?,?::jsonb,?::jsonb)",command,tenant,actor,store,action,json.write(payload),json.write(response));}
 private boolean sameJson(String a,String b){return Boolean.TRUE.equals(jdbc.queryForObject("select ?::jsonb=?::jsonb",Boolean.class,a,b));}
}
